
export const __effects = []
export function useState(v) { return [typeof v === 'function' ? v() : v, () => {}] }
export function useRef(v) { return { current: v } }
export function useCallback(fn) { return fn }
export function useMemo(fn) { return fn() }
export function useEffect(fn, deps) { __effects.push(fn); return () => {} }
export function useReducer(r, i) { return [typeof i === 'function' ? i() : i, () => {}] }
export function useLayoutEffect(fn) { __effects.push(fn); return () => {} }
